import { useEffect, useState } from "react"

export default function UserPage() {

    const apiUrl = "https://jsonplaceholder.typicode.com/users"
    const [users, setUsers] = useState(null)
    const [isLoading, setIsLoading] = useState(true)
    const [error, setError] = useState(null)

    const fetchUserData = async () => {
        try {
            const response = await fetch(apiUrl, { method: "GET" })

            if(!response.ok) throw new Error(`HTTP error: Status ${response.status}`);

            const usersData = await response.json()
            setUsers(usersData)

            setError(null)
        } catch(err) {
            setError(err.message)
            setUsers(null)
        } finally {
            setIsLoading(false)
        }
    } 

    useEffect(() => fetchUserData, [])

    return (
        <div className="h-screen w-full flex justify-center items-center">
            <div className="relative -z-10 h-full w-1/4 px-5 pt-20">
                {isLoading && <div className="absolute top-1/2 left-1/2 -translate-x-1/2 text-sm">Loading Users...</div>}
                {error && <div className="absolute top-1/2 left-1/2 -translate-x-1/2 text-sm">{error}</div>}
                {users && users.map((user) => (
                    <div className="text-sm">
                        <p>ID: {user.id}</p>
                        <p>Name: {user.name}</p>
                    </div>
                ))}
            </div>
            <div className="h-full w-3/4 bg-blue-300">

            </div>
        </div> 
    )
}
